var prog = root.querySelector(".mo1-album-ring-prog");
var grad = root.querySelector(".mo1-album-ring-grad");
var btn = root.querySelector(".mo1-album-ring-play");
var timeEl = root.querySelector(".mo1-album-ring-time");
