wave.setAttribute("stroke", "url(#" + uid + ")");
wave.setAttribute("pathLength", "100");
prog.setAttribute("pathLength", "100");
var N = 108, playing = true, amp = 0, ampT = 1, pos = 0, DUR = 214, drawn = false;
